#include <iostream>

// Pass-by-value: parameter is an isolated local copy
int cubeByValue(int n) {
    return n * n * n;
}

// Pass-by-reference using a pointer parameter
void cubeByReference(int* nPtr) {
    if (nPtr != nullptr) {
        *nPtr = (*nPtr) * (*nPtr) * (*nPtr);
    }
}

int main() {
    int val1 = 5;
    int result1 = cubeByValue(val1);
    std::cout << "Original val1: " << val1 << ", Result of cubeByValue: " << result1 << '\n';

    int val2 = 5;
    cubeByReference(&val2);
    std::cout << "Modified val2 directly by cubeByReference: " << val2 << '\n';

    return 0;
}

#include <iostream>
#include <iterator>
#include <algorithm>

// Demonstrating const array parameter notation and explicit size
int sumElements(const int values[], const std::size_t numberOfElements) {
    int sum = 0;
    for (std::size_t i = 0; i < numberOfElements; ++i) {
        sum += values[i];
    }
    return sum;
}

int main() {
    // Partial initialization: elements at index 3 and 4 are value-initialized to 0
    int numbers[5] = {50, 20, 30};

    std::cout << "Sum of elements: " << sumElements(numbers, 5) << '\n';

    // Using C++11 std::begin and std::end on built-in array
    std::sort(std::begin(numbers), std::end(numbers));

    std::cout << "Sorted array: ";
    for (const auto& elem : numbers) {
        std::cout << elem << ' ';
    }
    std::cout << '\n';

    return 0;
}
